def get_git_revision(path):
    """
    Get the git revision of a path

    :param path: Path to the git repository
    :returns: Git revision
    """
    return subprocess_check_output("git", "rev-parse", "HEAD", cwd=path)


def get_git_revision_short(path):
    """
    Get the git revision of a path

    :param path: Path to the git repository
    :returns: Git revision
    """
    return subprocess_check_output("git", "rev-parse", "--short", "HEAD", cwd=path)


